DROP TABLE IF EXISTS `led_entry_stages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `led_entry_stages` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `led_entry_id` bigint unsigned NOT NULL,
  `tahap` enum('P1','P2','P3','P4','P5') COLLATE utf8mb4_unicode_ci NOT NULL,
  `tanggal` date DEFAULT NULL,
  `penanggung_jawab` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `uraian` text COLLATE utf8mb4_unicode_ci,
  `catatan` text COLLATE utf8mb4_unicode_ci,
  `bukti` json DEFAULT NULL,
  `data_spesifik` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `led_entry_stages_led_entry_id_tahap_unique` (`led_entry_id`,`tahap`),
  CONSTRAINT `led_entry_stages_led_entry_id_foreign` FOREIGN KEY (`led_entry_id`) REFERENCES `led_entries` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12251 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
